create extension if not exists pgcrypto;
create table public.organizations (id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz not null default now());
create table public.organization_members (organization_id uuid references public.organizations(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,role text not null default 'technician' check(role in('owner','admin','technician','viewer')),primary key(organization_id,user_id));
create table public.manufacturers (id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique);
create table public.device_models (id uuid primary key default gen_random_uuid(),manufacturer_id uuid references public.manufacturers(id),name text not null,model_number text,recovery_notes text,unique(manufacturer_id,name,model_number));
create table public.diagnostic_sessions (id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,organization_id uuid references public.organizations(id) on delete set null,flow_id text not null,status text not null default 'active' check(status in('active','completed','archived')),manufacturer text not null,device_model text,answers jsonb not null default '{}'::jsonb,summary jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.diagnostic_evidence (id uuid primary key default gen_random_uuid(),session_id uuid not null references public.diagnostic_sessions(id) on delete cascade,evidence_type text not null check(evidence_type in('fact','user_claim','inference','ai_hypothesis')),source_type text not null check(source_type in('user','device','engine','knowledge')),statement text not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table public.diagnostic_actions (id uuid primary key default gen_random_uuid(),session_id uuid not null references public.diagnostic_sessions(id) on delete cascade,title text not null,risk_level text not null check(risk_level in('safe','low','medium','high','data_loss','service_required')),is_destructive boolean not null default false,guidance jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table public.action_results (id uuid primary key default gen_random_uuid(),action_id uuid not null references public.diagnostic_actions(id) on delete cascade,outcome text not null,notes text,created_at timestamptz not null default now());
create table public.security_states (id uuid primary key default gen_random_uuid(),session_id uuid not null references public.diagnostic_sessions(id) on delete cascade,provider text,state text not null,observed_message text,legitimate_routes jsonb not null default '[]'::jsonb,created_at timestamptz not null default now());
create table public.service_cases (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,session_id uuid references public.diagnostic_sessions(id),technician_id uuid references auth.users(id),status text not null default 'new' check(status in('new','diagnosing','waiting_for_customer','repair_required','repairing','testing','completed')),customer_name text,technician_notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.knowledge_articles (id uuid primary key default gen_random_uuid(),manufacturer_id uuid references public.manufacturers(id),title text not null,topic text not null,source_url text,source_name text not null,trust_level text not null default 'official' check(trust_level in('official','verified','community','unverified')),content text not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index diagnostic_sessions_user_updated_idx on public.diagnostic_sessions(user_id,updated_at desc); create index diagnostic_evidence_session_idx on public.diagnostic_evidence(session_id); create index service_cases_org_status_idx on public.service_cases(organization_id,status);
create or replace function public.is_org_member(org uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.organization_members where organization_id=org and user_id=auth.uid())$$;
create or replace function public.touch_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end;$$;
create trigger sessions_updated before update on public.diagnostic_sessions for each row execute procedure public.touch_updated_at(); create trigger cases_updated before update on public.service_cases for each row execute procedure public.touch_updated_at();
alter table public.organizations enable row level security;alter table public.organization_members enable row level security;alter table public.manufacturers enable row level security;alter table public.device_models enable row level security;alter table public.diagnostic_sessions enable row level security;alter table public.diagnostic_evidence enable row level security;alter table public.diagnostic_actions enable row level security;alter table public.action_results enable row level security;alter table public.security_states enable row level security;alter table public.service_cases enable row level security;alter table public.knowledge_articles enable row level security;
create policy "members read organisations" on public.organizations for select using(public.is_org_member(id)); create policy "members read membership" on public.organization_members for select using(user_id=auth.uid() or public.is_org_member(organization_id)); create policy "read manufacturers" on public.manufacturers for select using(true); create policy "read models" on public.device_models for select using(true); create policy "read knowledge" on public.knowledge_articles for select using(true);
create policy "own sessions" on public.diagnostic_sessions for all using(user_id=auth.uid() or public.is_org_member(organization_id)) with check(user_id=auth.uid() or public.is_org_member(organization_id));
create policy "own evidence" on public.diagnostic_evidence for all using(exists(select 1 from public.diagnostic_sessions s where s.id=session_id and(s.user_id=auth.uid() or public.is_org_member(s.organization_id)))) with check(exists(select 1 from public.diagnostic_sessions s where s.id=session_id and(s.user_id=auth.uid() or public.is_org_member(s.organization_id))));
create policy "own actions" on public.diagnostic_actions for all using(exists(select 1 from public.diagnostic_sessions s where s.id=session_id and(s.user_id=auth.uid() or public.is_org_member(s.organization_id)))) with check(exists(select 1 from public.diagnostic_sessions s where s.id=session_id and(s.user_id=auth.uid() or public.is_org_member(s.organization_id))));
create policy "own action results" on public.action_results for all using(exists(select 1 from public.diagnostic_actions a join public.diagnostic_sessions s on s.id=a.session_id where a.id=action_id and(s.user_id=auth.uid() or public.is_org_member(s.organization_id)))) with check(exists(select 1 from public.diagnostic_actions a join public.diagnostic_sessions s on s.id=a.session_id where a.id=action_id and(s.user_id=auth.uid() or public.is_org_member(s.organization_id))));
create policy "own security states" on public.security_states for all using(exists(select 1 from public.diagnostic_sessions s where s.id=session_id and(s.user_id=auth.uid() or public.is_org_member(s.organization_id)))) with check(exists(select 1 from public.diagnostic_sessions s where s.id=session_id and(s.user_id=auth.uid() or public.is_org_member(s.organization_id))));
create policy "org cases" on public.service_cases for all using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
